const treeData = $input.first().json;
const parsed = $('Parse GitHub URL').first().json;
const tree = treeData.tree || [];

const CODE_EXTENSIONS = ['.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.cs', '.go', '.rb', '.php', '.cpp', '.c', '.h', '.kt', '.swift'];
const EXCLUDE_PATTERNS = ['node_modules/', 'dist/', 'build/', 'vendor/', '.min.js', 'package-lock.json', 'yarn.lock', '.git/', 'test/fixtures/'];
const MAX_FILE_SIZE_BYTES = 50000; // keeps LLM prompt cost/context sane

const filtered = tree.filter(item => {
  if (item.type !== 'blob') return false;
  const path = item.path.toLowerCase();
  const hasCodeExt = CODE_EXTENSIONS.some(ext => path.endsWith(ext));
  const isExcluded = EXCLUDE_PATTERNS.some(p => path.includes(p));
  const sizeOk = !item.size || item.size <= MAX_FILE_SIZE_BYTES;
  return hasCodeExt && !isExcluded && sizeOk;
});

return filtered.map(item => ({
  json: {
    owner: parsed.owner,
    repo: parsed.repo,
    branch: parsed.branch,
    path: item.path,
    sha: item.sha,
    size: item.size
  }
}));

const raw = $json.text || $json.output || $json.content || '';
let parsed;

try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    file: $json.path,
    overall_score: null,
    overall_rating: 'Error',
    scorecard: [],
    findings: [{
      severity: 'High',
      parameter: 'N/A',
      location: 'N/A',
      finding: 'Failed to parse model output',
      impact: 'Review could not be completed',
      recommendation: 'Re-run review or inspect raw_output'
    }],
    recommended_tests: [],
    improvement_summary: {},
    raw_output: raw
  };
}

return [{ json: parsed }];

const files = $input.first().json.files || [];
const validScores = files.map(f => f.overall_score).filter(s => typeof s === 'number');
const overallScore = validScores.length
  ? Math.round(validScores.reduce((a, b) => a + b, 0) / validScores.length)
  : null;

const parsed = $('Parse GitHub URL').first().json;

return [{
  json: {
    repo: `${parsed.owner}/${parsed.repo}`,
    branch: parsed.branch,
    overall_score: overallScore,
    files_reviewed: files.length,
    files
  }
}];

const item = $input.first().json;

let body = item.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};

const query = item.query || {};

// Your UI is sending it under a few different key names — check all of them,
// in both the body and the query string.
const repoUrl = body.repoUrl || body.githubUrl || body.url
             || query.repoUrl || query.githubUrl || query.url;

const branch = body.branch || query.branch || 'main';

if (!repoUrl) {
  throw new Error(
    'No repo URL found. Body keys: ' + Object.keys(body).join(', ') +
    ' | Query keys: ' + Object.keys(query).join(', ')
  );
}

const match = repoUrl.match(/github\.com[:/]([^/]+)\/([^/.]+)(\.git)?/i);
if (!match) {
  throw new Error('Invalid GitHub repository URL: ' + repoUrl);
}

return [{
  json: {
    owner: match[1],
    repo: match[2],
    branch
  }
}];

const response = $input.first().json;

let content = '';
if (response.encoding === 'base64' && response.content) {
  content = Buffer.from(response.content, 'base64').toString('utf-8');
} else {
  content = response.content || '';
}

const MAX_CHARS = 2000;
const truncated = content.length > MAX_CHARS;
if (truncated) content = content.slice(0, MAX_CHARS) + '\n\n/* ...truncated for review... */';

return [{
  json: {
    path: response.path,
    sha: response.sha,
    content,
    truncated
  }
}];
